import StorageHelper, { REMEMBER_ME_OPTION } from './StorageHelper'

describe('Remember Me option storage', () => {
    beforeEach(() => {
        window.localStorage.clear()
    })

    it('returns undefined when no option has been stored', () => {
        expect(
            StorageHelper.getRememberMeOptionFromLocalStorage()
        ).toBeUndefined()
    })

    it.each([1, 2, 3])('stores and reads option %i', (option) => {
        StorageHelper.setRememberMeOptionInLocalStorage(option)

        expect(window.localStorage.getItem(REMEMBER_ME_OPTION)).toBe(
            JSON.stringify(option)
        )
        expect(StorageHelper.getRememberMeOptionFromLocalStorage()).toBe(option)
    })

    it.each([
        ['malformed JSON', '{not-json'],
        ['a JSON string', JSON.stringify('2')],
        ['a fractional number', JSON.stringify(2.5)],
        ['a boolean', JSON.stringify(true)],
        ['null', 'null'],
    ])('returns undefined for %s', (_description, value) => {
        window.localStorage.setItem(REMEMBER_ME_OPTION, value)

        expect(
            StorageHelper.getRememberMeOptionFromLocalStorage()
        ).toBeUndefined()
    })

    it('does not persist a non-integer option', () => {
        StorageHelper.setRememberMeOptionInLocalStorage(2.5)

        expect(window.localStorage.getItem(REMEMBER_ME_OPTION)).not.toBeTruthy()
    })
})

// Keep these lists in sync with the backend consumers, rather than the model alone:
// image, volumes, ports, environment, and caproverExtra:
// https://github.com/caprover/caprover/blob/master/src/user/oneclick/OneClickAppDeploymentHelper.ts
// depends_on (deployment order only):
// https://github.com/caprover/caprover/blob/master/src/user/oneclick/OneClickAppDeployManager.ts
// hostname, cap_add, and command:
// https://github.com/caprover/caprover/blob/master/src/utils/DockerComposeToServiceOverride.ts
const consumedServiceFields = [
    'image',
    'volumes',
    'ports',
    'environment',
    'depends_on',
    'hostname',
    'cap_add',
    'command',
    'caproverExtra',
]

const consumedExtraFields = [
    'dockerfileLines',
    'containerHttpPort',
    'notExposeAsWebApp',
    'websocketSupport',
]

function isRecord(value: unknown): value is Record<string, unknown> {
    return !!value && typeof value === 'object' && !Array.isArray(value)
}

// This checks field consumption only, not whether supported fields use valid syntax.
export function getIgnoredDockerComposeFields(compose: unknown): string[] {
    if (!isRecord(compose)) return []

    // DockerComposeEntry supplies its own captainVersion and caproverOneClickApp.
    // Only services from the pasted document reach the deployment consumers.
    const ignored = Object.keys(compose).filter((key) => key !== 'services')
    const services = compose.services
    if (!isRecord(services)) return ignored

    Object.keys(services).forEach((serviceName) => {
        const service = services[serviceName]
        if (!isRecord(service)) return

        const prefix = `services.${serviceName}`
        Object.keys(service).forEach((key) => {
            if (!consumedServiceFields.includes(key)) {
                ignored.push(`${prefix}.${key}`)
            } else if (key === 'caproverExtra') {
                const extra = service[key]
                if (!isRecord(extra)) return
                Object.keys(extra).forEach((extraKey) => {
                    if (!consumedExtraFields.includes(extraKey)) {
                        ignored.push(`${prefix}.caproverExtra.${extraKey}`)
                    }
                })
            }
        })
    })

    return ignored
}

import * as yaml from 'yaml'
import { IDockerComposeService } from '../models/IOneClickAppModels'
import Utils from './Utils'

export default class DockerComposeToServiceOverride {
    /**
     * Converts the unsupported docker compose parameters to CapRover service override definition.
     * Port, replicas, env vars, volumes, and image are supplied through CapRover definition,
     * network will be set to captain-overlay restart_policy is not generally needed,
     * by default docker services restart automatically.
     * Only parse parameters that are not from the aforementioned list.
     * The only useful parameter that we are parsing at the moment is hostname: https://github.com/caprover/caprover/issues/404
     *
     * @param docker compose service definition
     * @returns the override service definition in yaml format
     */
    static convertUnconsumedComposeParametersToServiceOverride(
        compose: IDockerComposeService
    ) {
        const overrides = [] as any[]
        overrides.push(DockerComposeToServiceOverride.parseHostname(compose))
        overrides.push(DockerComposeToServiceOverride.parseCapAdd(compose))
        overrides.push(DockerComposeToServiceOverride.parseCommand(compose))
        // Add more overrides here if needed

        let mergedOverride = {} as any
        overrides.forEach((o) => {
            mergedOverride = Utils.mergeObjects(mergedOverride, o)
        })
        if (Object.keys(mergedOverride).length === 0) {
            return undefined
        }

        return yaml.stringify(mergedOverride)
    }

    private static parseCommand(compose: IDockerComposeService) {
        const override = {} as any

        function parseDockerCMD(cmdString: string) {
            // Matches sequences inside quotes or sequences without spaces
            const regex = /[^\s"']+|"([^"]*)"|'([^']*)'/g
            let match
            let args = []

            while ((match = regex.exec(cmdString))) {
                // If matched quotes, add the first group that is not undefined
                if (match[1]) {
                    args.push(match[1])
                } else if (match[2]) {
                    args.push(match[2])
                } else {
                    args.push(match[0])
                }
            }

            return args
        }

        if (!!compose.command) {
            override.TaskTemplate = {
                ContainerSpec: {
                    Command: Array.isArray(compose.command)
                        ? compose.command
                        : parseDockerCMD(compose.command),
                },
            }
        }

        return override
    }

    private static parseHostname(compose: IDockerComposeService) {
        const override = {} as any
        const hostname = !!compose.hostname ? `${compose.hostname}`.trim() : ''
        if (!!compose.hostname) {
            override.TaskTemplate = {
                ContainerSpec: {
                    Hostname: hostname,
                },
            }
        }

        return override
    }

    private static parseCapAdd(compose: IDockerComposeService) {
        const override = {} as any
        if (!!compose.cap_add && Array.isArray(compose.cap_add)) {
            const capabilityAdd = compose.cap_add
                .map((cap) => cap.toUpperCase())
                .map((cap) => (cap.startsWith(`CAP`) ? cap : `CAP_${cap}`))
            override.TaskTemplate = {
                ContainerSpec: {
                    CapabilityAdd: capabilityAdd,
                },
            }
        }

        return override
    }
}

